(ROOT/'index.html').write_text(page)

# XLSX средствами стандартной библиотеки: перенос строк, фильтр, закреплённая шапка.
def sheet_xml(rows,widths,height=138):
 cols=''.join(f'<col min="{i}" max="{i}" width="{w}" customWidth="1"/>' for i,w in enumerate(widths,1))
 out=[]
 for n,row in enumerate(rows,1):
  cells=[]
  for j,v in enumerate(row):
   ref=chr(65+j)+str(n)
   cells.append(f'<c r="{ref}" s="{1 if n==1 else 2}" t="inlineStr"><is><t xml:space="preserve">{escape(str(v))}</t></is></c>')
  out.append(f'<row r="{n}" ht="{30 if n==1 else height}" customHeight="1">'+''.join(cells)+'</row>')
 return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>'+cols+'</cols><sheetData>'+''.join(out)+f'</sheetData><autoFilter ref="A1:{chr(64+len(widths))}{len(rows)}"/><pageSetup orientation="landscape" paperSize="8" fitToWidth="1" fitToHeight="0"/></worksheet>'
sheets=[('Февраль',[HEADERS]+[row_cells(r) for r in ROWS],[9,40,45,64,82]),('Материалы',[['Дата','Название','Что подготовить','Статус']]+[[f'{r[0]:02}.02',r[1],r[8],'Состав — на согласование; механика — замысел'] for r in ROWS],[9,40,90,40]),('О таблице',[['Параметр','Значение'],['Статус','Проект февраля на согласование'],['Форма',INTRO],['Привязка',LEGEND],['Проверка',LIMITS],['Основа','Концепция v2, E-05 от 08.09.2026; команда собирать помесячно после января']],[25,140])]
